mapper.insert:
INSERT INTO OP_MANAGER_HIST ( USER_ID , HIST_SEQ , LOGIN_ID , USER_NAME , EMAIL , PHONE_NUMBER , STATUS_CODE , UPDATED_DATE , LOCGOV_CODE , BANK_CODE , EMP_ID , PSITN_NM , PSITN_DEPT_NM , OFCPS_NM , AUTHORITY , INFO_UPDT_DE , REG_USERTXT ) SELECT M.USER_ID , ( SELECT IFNULL(MAX(H.HIST_SEQ), 0) + 1 FROM OP_MANAGER_HIST H WHERE M.USER_ID = H.USER_ID ) , M.LOGIN_ID , M.USER_NAME , M.EMAIL , M.PHONE_NUMBER , M.STATUS_CODE , M.UPDATED_DATE , M.LOCGOV_CODE , M.BANK_CODE , M.EMP_ID , M.PSITN_NM , M.PSITN_DEPT_NM , M.OFCPS_NM , ( SELECT AUTHORITY FROM OP_USER_ROLE R WHERE R.USER_ID = M.USER_ID AND R.AUTHORITY LIKE 'ROLE_ADMIN_%' AND R.AUTHORITY != 'ROLE_ADMIN_CALL' ) , M.INFO_UPDT_DE , #{regUsertxt} FROM OP_MANAGER M
M.USER_ID = #{userId}
M.LOGIN_ID = crypto_enc('normal', #{loginId},'')
M.USER_ID IN (
#{item}
)
